{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2172-07-16 15:10:00",
      "speaker": "Doctor",
      "text": "Hello, Mr. ___. I'm Dr. ___, part of your care team. You're here for your autologous stem cell transplant for multiple myeloma. How are you feeling today?"
    },
    {
      "turn_number": 2,
      "time": "2172-07-16 15:11:00",
      "speaker": "Patient",
      "text": "Hi, doctor. I’m doing okay. A bit nervous, but ready to get this done. Is everything set?"
    },
    {
      "turn_number": 3,
      "time": "2172-07-16 15:12:00",
      "speaker": "Doctor",
      "text": "Yes, we’re all set. First, we’ll place a central line so we can give the chemotherapy and stem cells safely. It’ll be done with ultrasound and X-ray guidance."
    },
    {
      "turn_number": 4,
      "time": "2172-07-16 15:13:00",
      "speaker": "Patient",
      "text": "I remember last time they had trouble placing it. Is that a concern?"
    },
    {
      "turn_number": 5,
      "time": "2172-07-16 15:14:00",
      "speaker": "Doctor",
      "text": "We’re aware of that. The team is experienced and will use imaging to make sure it goes smoothly. If needed, we’ll have backup options."
    },
    {
      "turn_number": 6,
      "time": "2172-07-16 15:15:00",
      "speaker": "Patient",
      "text": "Okay, that makes me feel better."
    },
    {
      "turn_number": 7,
      "time": "2172-07-16 18:10:00",
      "speaker": "Doctor",
      "text": "The line was placed successfully in your right internal jugular vein. It’s in good position and ready to use."
    },
    {
      "turn_number": 8,
      "time": "2172-07-16 18:11:00",
      "speaker": "Patient",
      "text": "Great. Any side effects to watch for?"
    },
    {
      "turn_number": 9,
      "time": "2172-07-16 18:12:00",
      "speaker": "Doctor",
      "text": "We’ll monitor for infection or bleeding. Let us know if you have pain, swelling, or fever at the site."
    },
    {
      "turn_number": 10,
      "time": "2172-07-17 09:00:00",
      "speaker": "Doctor",
      "text": "We’re starting the melphalan chemotherapy today. This prepares your body to receive the stem cells."
    },
    {
      "turn_number": 11,
      "time": "2172-07-17 09:01:00",
      "speaker": "Patient",
      "text": "How long will this last?"
    },
    {
      "turn_number": 12,
      "time": "2172-07-17 09:02:00",
      "speaker": "Doctor",
      "text": "Just a few days. Then we’ll infuse your stem cells. You may feel tired or nauseated, but we’ll manage symptoms."
    },
    {
      "turn_number": 13,
      "time": "2172-07-20 10:00:00",
      "speaker": "Doctor",
      "text": "Today is the big day — we’ll be transplanting your stem cells. You’ve tolerated the chemo well."
    },
    {
      "turn_number": 14,
      "time": "2172-07-20 10:01:00",
      "speaker": "Patient",
      "text": "That’s a relief. How will I feel after the transplant?"
    },
    {
      "turn_number": 15,
      "time": "2172-07-20 10:02:00",
      "speaker": "Doctor",
      "text": "You’ll be more vulnerable to infections for a while as your counts drop. We’ll give Neupogen to help your white blood cells recover."
    },
    {
      "turn_number": 16,
      "time": "2172-07-20 10:03:00",
      "speaker": "Patient",
      "text": "And the acyclovir I’m on?"
    },
    {
      "turn_number": 17,
      "time": "2172-07-20 10:04:00",
      "speaker": "Doctor",
      "text": "Yes, that’s to prevent viral infections. You’ll stay on it for now."
    },
    {
      "turn_number": 18,
      "time": "2172-07-21 14:00:00",
      "speaker": "Doctor",
      "text": "Your blood counts are dropping as expected. We’re watching closely."
    },
    {
      "turn_number": 19,
      "time": "2172-07-21 14:01:00",
      "speaker": "Patient",
      "text": "I’ve been a bit dizzy. Is that normal?"
    },
    {
      "turn_number": 20,
      "time": "2172-07-21 14:02:00",
      "speaker": "Doctor",
      "text": "Could be from low counts or dehydration. We’ll check your labs and fluids."
    },
    {
      "turn_number": 21,
      "time": "2172-07-22 08:00:00",
      "speaker": "Doctor",
      "text": "You’re developing some swelling in your legs. We think it’s from the IV fluids."
    },
    {
      "turn_number": 22,
      "time": "2172-07-22 08:01:00",
      "speaker": "Patient",
      "text": "I’ve had that before. I used to take Lasix at home."
    },
    {
      "turn_number": 23,
      "time": "2172-07-22 08:02:00",
      "speaker": "Doctor",
      "text": "We’ll give IV Lasix to help. We’ll monitor your kidney function."
    },
    {
      "turn_number": 24,
      "time": "2172-07-23 09:00:00",
      "speaker": "Doctor",
      "text": "You’ve developed left lower abdominal pain and diarrhea. We’re concerned about infection."
    },
    {
      "turn_number": 25,
      "time": "2172-07-23 09:01:00",
      "speaker": "Patient",
      "text": "It’s pretty painful. Could it be from the transplant?"
    },
    {
      "turn_number": 26,
      "time": "2172-07-23 09:02:00",
      "speaker": "Doctor",
      "text": "Possibly, but we need to rule out diverticulitis. We’re ordering a CT scan."
    },
    {
      "turn_number": 27,
      "time": "2172-07-23 13:00:00",
      "speaker": "Doctor",
      "text": "The CT shows mild diverticulitis at the splenic flexure. No abscess, which is good."
    },
    {
      "turn_number": 28,
      "time": "2172-07-23 13:01:00",
      "speaker": "Patient",
      "text": "What does that mean?"
    },
    {
      "turn_number": 29,
      "time": "2172-07-23 13:02:00",
      "speaker": "Doctor",
      "text": "It’s inflammation in small pouches in your colon. We’ll start IV antibiotics — meropenem — until your counts recover."
    },
    {
      "turn_number": 30,
      "time": "2172-07-23 13:03:00",
      "speaker": "Patient",
      "text": "Will I need surgery?"
    },
    {
      "turn_number": 31,
      "time": "2172-07-23 13:04:00",
      "speaker": "Doctor",
      "text": "No, not now. This is mild and not perforated. We’ll treat it with antibiotics."
    },
    {
      "turn_number": 32,
      "time": "2172-07-24 10:00:00",
      "speaker": "Doctor",
      "text": "Your C. diff test came back negative, so it’s not that. We’re continuing meropenem."
    },
    {
      "turn_number": 33,
      "time": "2172-07-24 10:01:00",
      "speaker": "Patient",
      "text": "Good. I’ve been worried about that."
    },
    {
      "turn_number": 34,
      "time": "2172-07-25 09:00:00",
      "speaker": "Doctor",
      "text": "You mentioned a loose tooth?"
    },
    {
      "turn_number": 35,
      "time": "2172-07-25 09:01:00",
      "speaker": "Patient",
      "text": "Yes, it’s been wiggly for two days. No pain or swelling."
    },
    {
      "turn_number": 36,
      "time": "2172-07-25 09:02:00",
      "speaker": "Doctor",
      "text": "We examined it — no signs of infection. It should settle. See your dentist after recovery."
    },
    {
      "turn_number": 37,
      "time": "2172-07-26 11:00:00",
      "speaker": "Doctor",
      "text": "The repeat CT shows improvement in the diverticulitis. No abscess. That’s excellent."
    },
    {
      "turn_number": 38,
      "time": "2172-07-26 11:01:00",
      "speaker": "Patient",
      "text": "So I’m getting better?"
    },
    {
      "turn_number": 39,
      "time": "2172-07-26 11:02:00",
      "speaker": "Doctor",
      "text": "Yes. We’ll switch you to oral antibiotics — cipro and flagyl — for two weeks once your counts allow."
    },
    {
      "turn_number": 40,
      "time": "2172-07-27 08:00:00",
      "speaker": "Doctor",
      "text": "Your white count is starting to recover. That’s a sign your stem cells are engrafting."
    },
    {
      "turn_number": 41,
      "time": "2172-07-27 08:01:00",
      "speaker": "Patient",
      "text": "That’s great news!"
    },
    {
      "turn_number": 42,
      "time": "2172-07-28 07:00:00",
      "speaker": "Doctor",
      "text": "We checked your hepatitis B viral load. It’s undetectable — good. You’ll stay on lamivudine to prevent reactivation."
    },
    {
      "turn_number": 43,
      "time": "2172-07-28 07:02:00",
      "speaker": "Patient",
      "text": "And the liver enzymes? They were high before."
    },
    {
      "turn_number": 44,
      "time": "2172-07-28 07:03:00",
      "speaker": "Doctor",
      "text": "They’re still elevated — AST and ALT are up. We think it’s partly from past alcohol use. You’ll need close follow-up."
    },
    {
      "turn_number": 45,
      "time": "2172-07-28 07:04:00",
      "speaker": "Patient",
      "text": "I haven’t had a drink in weeks. I’m trying."
    },
    {
      "turn_number": 46,
      "time": "2172-07-28 07:05:00",
      "speaker": "Doctor",
      "text": "That’s important. We’ll support you. Your liver can heal with time."
    },
    {
      "turn_number": 47,
      "time": "2172-07-29 09:00:00",
      "speaker": "Doctor",
      "text": "Your blood cultures and urine culture are negative — no infection. That’s reassuring."
    },
    {
      "turn_number": 48,
      "time": "2172-07-29 09:01:00",
      "speaker": "Patient",
      "text": "Good. I’ve been feeling stronger."
    },
    {
      "turn_number": 49,
      "time": "2172-07-30 10:00:00",
      "speaker": "Doctor",
      "text": "We’re switching you to oral cipro and flagyl for the diverticulitis. Finish the full course."
    },
    {
      "turn_number": 50,
      "time": "2172-07-30 10:01:00",
      "speaker": "Patient",
      "text": "Got it. Any dietary changes?"
    },
    {
      "turn_number": 51,
      "time": "2172-07-30 10:02:00",
      "speaker": "Doctor",
      "text": "Low fiber for now. We’ll guide you back to normal eating gradually."
    },
    {
      "turn_number": 52,
      "time": "2172-07-31 08:00:00",
      "speaker": "Doctor",
      "text": "Your blood pressure has been a bit high. We’re increasing your amlodipine to 10 mg daily."
    },
    {
      "turn_number": 53,
      "time": "2172-07-31 08:01:00",
      "speaker": "Patient",
      "text": "Okay. I’ve been on that for years."
    },
    {
      "turn_number": 54,
      "time": "2172-08-01 09:00:00",
      "speaker": "Doctor",
      "text": "Your endocrinology team reviewed your diabetes. We’re reducing your glargine to 25 units at bedtime."
    },
    {
      "turn_number": 55,
      "time": "2172-08-01 09:01:00",
      "speaker": "Patient",
      "text": "Why the change?"
    },
    {
      "turn_number": 56,
      "time": "2172-08-01 09:02:00",
      "speaker": "Doctor",
      "text": "Your sugars have been stable. We want to avoid lows. Keep using your sliding scale for Humalog and record your levels."
    },
    {
      "turn_number": 57,
      "time": "2172-08-01 09:03:00",
      "speaker": "Patient",
      "text": "And gabapentin?"
    },
    {
      "turn_number": 58,
      "time": "2172-08-01 09:04:00",
      "speaker": "Doctor",
      "text": "We’re stopping it. Nortriptyline will continue for your neuropathy."
    },
    {
      "turn_number": 59,
      "time": "2172-08-02 10:00:00",
      "speaker": "Doctor",
      "text": "We’re starting Bactrim tomorrow to prevent infections while your counts are still recovering."
    },
    {
      "turn_number": 60,
      "time": "2172-08-02 10:01:00",
      "speaker": "Patient",
      "text": "Is that safe with my kidney function?"
    },
    {
      "turn_number": 61,
      "time": "2172-08-02 10:02:00",
      "speaker": "Doctor",
      "text": "Yes, your creatinine is 0.6 — excellent. We’ll monitor, but it’s safe to start."
    },
    {
      "turn_number": 62,
      "time": "2172-08-03 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing really well. Pain-free, eating well, and walking. We’re planning discharge in two days."
    },
    {
      "turn_number": 63,
      "time": "2172-08-03 09:01:00",
      "speaker": "Patient",
      "text": "That’s great. What about the INH for TB?"
    },
    {
      "turn_number": 64,
      "time": "2172-08-03 09:02:00",
      "speaker": "Doctor",
      "text": "Start it about a week after your counts recover. We’ll monitor your liver closely because of your history."
    },
    {
      "turn_number": 65,
      "time": "2172-08-04 08:00:00",
      "speaker": "Doctor",
      "text": "We’ll remove your central line today. It’s no longer needed."
    },
    {
      "turn_number": 66,
      "time": "2172-08-04 08:01:00",
      "speaker": "Patient",
      "text": "Will it hurt?"
    },
    {
      "turn_number": 67,
      "time": "2172-08-04 08:02:00",
      "speaker": "Doctor",
      "text": "Just a little pressure. We’ll numb the area. It’ll be quick."
    },
    {
      "turn_number": 68,
      "time": "2172-08-04 08:30:00",
      "speaker": "Doctor",
      "text": "Line is out — no issues. Site looks clean."
    },
    {
      "turn_number": 69,
      "time": "2172-08-05 08:00:00",
      "speaker": "Doctor",
      "text": "Today’s the day — you’re going home. You’ve done very well."
    },
    {
      "turn_number": 70,
      "time": "2172-08-05 08:01:00",
      "speaker": "Patient",
      "text": "I’m so glad. What do I need to watch for?"
    },
    {
      "turn_number": 71,
      "time": "2172-08-05 08:02:00",
      "speaker": "Doctor",
      "text": "Fever, worsening abdominal pain, or shortness of breath — call us. Finish your antibiotics and monitor your sugars."
    },
    {
      "turn_number": 72,
      "time": "2172-08-05 08:03:00",
      "speaker": "Patient",
      "text": "And follow-up?"
    },
    {
      "turn_number": 73,
      "time": "2172-08-05 08:04:00",
      "speaker": "Doctor",
      "text": "Oncology, endocrinology, and primary care — all scheduled. We’ll see you soon."
    },
    {
      "turn_number": 74,
      "time": "2172-08-05 08:05:00",
      "speaker": "Patient",
      "text": "Thank you, doctor. I really appreciate everything."
    },
    {
      "turn_number": 75,
      "time": "2172-08-05 08:06:00",
      "speaker": "Doctor",
      "text": "You did the hard work. Take care, and we’ll be in touch."
    },
    {
      "turn_number": 76,
      "time": "2172-08-05 08:07:00",
      "speaker": "Patient",
      "text": "One more thing — my hernia?"
    },
    {
      "turn_number": 77,
      "time": "2172-08-05 08:08:00",
      "speaker": "Doctor",
      "text": "It’s reducible and not causing issues. Monitor it. See surgery if it becomes painful or doesn’t go back in."
    },
    {
      "turn_number": 78,
      "time": "2172-08-05 08:09:00",
      "speaker": "Patient",
      "text": "Got it. Thanks again."
    },
    {
      "turn_number": 79,
      "time": "2172-08-05 08:10:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Safe travels home."
    },
    {
      "turn_number": 80,
      "time": "2172-08-05 08:11:00",
      "speaker": "Patient",
      "text": "I’ll follow all the instructions."
    },
    {
      "turn_number": 81,
      "time": "2172-08-05 08:12:00",
      "speaker": "Doctor",
      "text": "Perfect. We’re proud of your progress."
    },
    {
      "turn_number": 82,
      "time": "2172-08-05 08:13:00",
      "speaker": "Patient",
      "text": "It feels good to be on the mend."
    },
    {
      "turn_number": 83,
      "time": "2172-08-05 08:14:00",
      "speaker": "Doctor",
      "text": "You’ve come a long way. Keep up the good work."
    },
    {
      "turn_number": 84,
      "time": "2172-08-05 08:15:00",
      "speaker": "Patient",
      "text": "I will. Thank you."
    },
    {
      "turn_number": 85,
      "time": "2172-08-05 08:16:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. ___. We’ll see you soon."
    }
  ],
  "summary": {
    "admission_start": "2172-07-16 15:05:00",
    "admission_end": "2172-08-05 15:05:00",
    "summary_paragraph": "Mr. ___ was admitted for an autologous stem cell transplant for IgA multiple myeloma. The transplant was performed successfully after placement of a central venous catheter. During the hospitalization, he developed mild diverticulitis on post-transplant day 3, which was treated with intravenous meropenem followed by oral ciprofloxacin and metronidazole, with clinical and radiographic improvement. He experienced transient lower extremity edema managed with IV furosemide, and his liver enzymes rose, attributed partly to prior alcohol use. His diabetes was managed with reduced insulin glargine and sliding scale lispro, and gabapentin was discontinued for neuropathy. He completed prophylactic antiviral and PJP prophylaxis, and was discharged home in stable condition with plans to start INH for latent tuberculosis and close outpatient follow-up.",
    "problems": [
      "Multiple myeloma, without mention of having achieved remission",
      "Diabetes with neurological manifestations, type II or unspecified type, uncontrolled",
      "Diverticulitis of colon (without mention of hemorrhage)",
      "Unspecified essential hypertension",
      "Polyneuropathy in diabetes",
      "Obstructive sleep apnea (adult)(pediatric)",
      "Sickle-cell trait",
      "Other specified disorders of the teeth and supporting structures",
      "Alcohol abuse, unspecified",
      "Personal history of malignant neoplasm of testis",
      "Personal history of malignant neoplasm of prostate",
      "Long-term (current) use of insulin"
    ]
  }
}
